class Solution:
    def productExceptSelf(self, nums: List[int]) -> List[int]:
        n = len(nums)
        res = [1] * n
        p = 1
        for i in range(n):
            res[i] = p
            p *= nums[i]
        s = 1
        for i in range(n - 1, -1, -1):
            res[i] *= s
            s *= nums[i]
        return res

reference_solution.javascript:
function productExceptSelf(nums) {
    const n = nums.length;
    const res = new Array(n).fill(1);
    let p = 1;
    for (let i = 0; i < n; i++) {
        res[i] = p;
        p *= nums[i];
    }
    let s = 1;
    for (let i = n - 1; i >= 0; i--) {
        res[i] *= s;
        s *= nums[i];
    }
    return res;
}
